// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for privacy: owner-only folder, redaction, retention
// Flo: tmp dir > lock > read ACL and write a file after > purge old rows > redact text
// I/O: folders and rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const priv = @import("ru-safe-priv.zig"); const data = @import("st-stat-data.zig"); const mock = @import("te-mock-page.zig"); const file = @import("st-stor-file.zig"); const T = std.testing;
test "body log hides text unless enabled, token keeps the length" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try T.expectEqualStrings("hello", priv.bodyLog(alo, "hello", true)); const tok = priv.bodyLog(alo, "hello", false); try T.expect(std.mem.find(u8, tok, "hello") == null); try T.expect(std.mem.endsWith(u8, tok, ":5»")); }
test "owner-only folder: only the owner SID remains and the owner can still write" { if (builtin.os.tag != .windows) return error.SkipZigTest; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); const abs = try mock.absPath(T.allocator, T.io, rel); defer T.allocator.free(abs); const sr = T.environ.getAlloc(T.allocator, "SystemRoot") catch try T.allocator.dupe(u8, ""); defer T.allocator.free(sr); const who = try priv.ownerId(T.allocator, T.io, sr); defer T.allocator.free(who); try T.expect(who.len > 6 and who[0] == '*'); try priv.ownerOnly(T.allocator, T.io, abs, who); const res = try std.process.run(T.allocator, T.io, .{ .argv = &.{ "icacls", abs }, .stdout_limit = .limited(8192), .stderr_limit = .limited(8192) }); defer T.allocator.free(res.stdout); defer T.allocator.free(res.stderr); try T.expect(std.mem.find(u8, res.stdout, "BUILTIN\\Users") == null); try T.expect(std.mem.find(u8, res.stdout, "Everyone") == null); try T.expect(std.mem.find(u8, res.stdout, "(OI)(CI)(F)") != null); const probe = try std.fs.path.join(T.allocator, &.{ abs, "after-lock.txt" }); defer T.allocator.free(probe); try file.fileAtom(T.allocator, T.io, probe, "still writable"); try T.expect(file.fileHas(T.io, probe)); }
test "a bad owner id fails and does not touch the folder permissions" { if (builtin.os.tag != .windows) return error.SkipZigTest; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); const abs = try mock.absPath(T.allocator, T.io, rel); defer T.allocator.free(abs); try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, abs, "Admin")); try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, abs, "")); try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, abs, "*S-1-5-99-0-0-0-0")); const probe = try std.fs.path.join(T.allocator, &.{ abs, "still-open.txt" }); defer T.allocator.free(probe); try file.fileAtom(T.allocator, T.io, probe, "ok"); }
test "owner-only on a missing folder fails" { if (builtin.os.tag == .windows) { const sr = T.environ.getAlloc(T.allocator, "SystemRoot") catch try T.allocator.dupe(u8, ""); defer T.allocator.free(sr); const who = try priv.ownerId(T.allocator, T.io, sr); defer T.allocator.free(who); try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, "C:\\no-such-za-dir-xyz", who)); } else { try T.expectError(error.Fail, priv.ownerOnly(T.allocator, T.io, "/no/such/za/dir", "")); } }
test "purge removes only old messages and keeps sends" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); const D: i64 = 86400000; try sto.msgAdd("c", "them", "old", 1 * D); try sto.msgAdd("c", "them", "edge", 70 * D); try sto.msgAdd("c", "them", "new", 99 * D); _ = try sto.sendBegin("c", "x", 1); try sto.sendDone("c", "x", 2); try T.expectEqual(@as(u32, 1), try sto.purge(100 * D, 30)); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const left = try sto.msgTail(aren.allocator(), "c", 10); try T.expectEqual(@as(usize, 2), left.len); try T.expectEqualStrings("edge", left[0].body); try T.expect(try sto.sendBegin("c", "x", 3) == .dup); try T.expectEqual(@as(u32, 0), try sto.purge(100 * D, 30)); try T.expectEqual(@as(u32, 0), try sto.purge(100 * D, 0)); }
